function sampleExamples(examples: readonly string[], n: number): string[] {
  if (examples.length <= n) return [...examples]
  const shuffled = [...examples]
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]]
  }
  return shuffled.slice(0, n)
}

async function savePromptsToLibrary(
  prompts: string[],
  bundleLabel: string,
  source: 'grok-generated' | 'static-bundle',
  extraTags?: string[],
) {
  const tags = extraTags ?? bundleTags(bundleLabel, source)
  try {
    const res = await fetch('/api/prompt-library', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        characterId: GLOBAL_CHARACTER_ID,
        prompts,
        label: bundleLabel,
        tags,
        skipDuplicates: true,
      }),
    })
    const data = await res.json()
    if (res.ok && data.saved > 0) {
      toast.success(`Saved ${data.saved} prompts to library (${tags.join(', ')})`)
    }
  } catch {
    // Non-blocking — generation still succeeds
  }
}

