// ─── Instagram Bundles ──────────────────────────────────────────

function pickEvenly<T>(arr: readonly T[], n: number): T[] {
  if (n >= arr.length) return [...arr]
  if (n <= 0) return []
  const step = arr.length / n
  const out: T[] = []
  for (let i = 0; i < n; i++) out.push(arr[Math.floor(i * step)])
  return out
}

export interface InstagramBundle {
  label: string
  description: string
  /** Branded niche full feed — pulls from niche-prompts.ts */
  nicheId?: string
  /** Deterministic bundles pull fixed prompts straight from the library. */
  recipe?: { theme: string; count: number }[]
  /** AI variety bundles generate fresh prompts via Grok, seeded from these long-form themes. */
  aiVariety?: { referenceThemes: string[]; count: number }
}

